import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/data/data.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/datasource.mocks.dart';

import 'widget.dart';

void main() {
  final MockPreferenceDatasource mockPreferenceDatasource = MockPreferenceDatasource();

  late SettingsRepository settingsRepository;
  late StreamController<AppThemeMode> themeModeController;

  setUp(() {
    settingsRepository = SettingsRepositoryImpl(mockPreferenceDatasource);
    themeModeController = StreamController<AppThemeMode>.broadcast();

    when(mockPreferenceDatasource.themeMode).thenReturn(AppThemeMode.system);
    when(mockPreferenceDatasource.setThemeMode(any)).thenReturn(null);
    when(mockPreferenceDatasource.getToken()).thenAnswer((_) async => null);
    when(mockPreferenceDatasource.setToken(any)).thenAnswer((_) async {});
  });

  tearDown(() {
    themeModeController.close();
  });

  group('ProfilePage', () {
    Widget profileWidget() => buildWidget(
          providers: [
            Provider<SettingsRepository>.value(value: settingsRepository),
          ],
          child: const ProfilePage(),
        );

    testWidgets('should display theme mode read synchronously on start', (WidgetTester tester) async {
      await tester.pumpWidget(profileWidget());

      expect(find.text('Системная'), findsOneWidget);
    });

    testWidgets('should update displayed theme mode when themeModeStream emits', (WidgetTester tester) async {
      await tester.pumpWidget(profileWidget());

      settingsRepository.setThemeMode(AppThemeMode.dark);
      await tester.pump();

      expect(find.text('Тёмная'), findsOneWidget);
      expect(find.text('Системная'), findsNothing);

      settingsRepository.setThemeMode(AppThemeMode.light);
      await tester.pump();

      expect(find.text('Светлая'), findsOneWidget);
      expect(find.text('Тёмная'), findsNothing);
    });
  });
}

